def process_local_orders_hourly():
    """Process exactly one page of orders from the local checkpointed API.

    Reads ``/batches/last``, fetches at most one page from ``/orders``,
    validates every required field, computes the exact six-key integer batch,
    and posts it to ``/batches``. An empty page is a successful no-op. Any
    transport, HTTP, JSON, shape, or field validation failure raises without
    posting partial data or maintaining a local checkpoint.

    Returns a status dictionary describing the no-op or accepted batch. This
    function has an external POST side effect when orders are present; the API
    checkpoint remains the sole source of progress.
    """
    import json
    import logging
    import urllib.error
    import urllib.parse
    import urllib.request
    from collections import defaultdict
    from datetime import date as Date

    log = logging.getLogger(__name__)
    base_url = "http://127.0.0.1:8125"
    timeout_seconds = 30
    expected_payload_keys = {
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_revenue_cents",
        "revenue_by_region_cents",
    }

    def require_int(value, field):
        if type(value) is not int:
            raise RuntimeError(f"Malformed response: {field} must be an integer")
        return value

    def get_json(url):
        log.info("PHASE GET %s", url)
        request = urllib.request.Request(
            url,
            method="GET",
            headers={"Accept": "application/json"},
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
                status = response.status
                body = response.read()
                content_type = response.headers.get("Content-Type", "")
        except urllib.error.HTTPError as exc:
            body = exc.read()
            raise RuntimeError(
                f"GET {url} failed with HTTP {exc.code}: {body[:500]!r}"
            ) from exc
        except Exception as exc:
            raise RuntimeError(f"GET {url} failed: {exc}") from exc

        if not 200 <= status < 300:
            raise RuntimeError(f"GET {url} returned non-2xx HTTP {status}")
        try:
            return json.loads(body.decode("utf-8"))
        except Exception as exc:
            raise RuntimeError(
                f"GET {url} returned malformed JSON (Content-Type {content_type!r})"
            ) from exc

    checkpoint = get_json(f"{base_url}/batches/last")
    if not isinstance(checkpoint, dict) or set(checkpoint) != {"last_seq"}:
        raise RuntimeError(
            'Malformed /batches/last response: expected exactly {"last_seq": N}'
        )
    last_seq = require_int(checkpoint["last_seq"], "last_seq")
    if last_seq < 0:
        raise RuntimeError(
            "Malformed /batches/last response: last_seq must be nonnegative"
        )

    query = urllib.parse.urlencode({"after": last_seq})
    collection = get_json(f"{base_url}/orders?{query}")
    if isinstance(collection, list):
        orders = collection
    elif isinstance(collection, dict):
        list_fields = [
            (key, value)
            for key, value in collection.items()
            if isinstance(value, list)
        ]
        preferred = [
            item
            for item in list_fields
            if item[0] in ("orders", "items", "data", "results")
        ]
        if len(preferred) == 1:
            orders = preferred[0][1]
        elif len(list_fields) == 1:
            orders = list_fields[0][1]
        else:
            raise RuntimeError(
                "Malformed /orders response: expected a list or an unambiguous collection envelope"
            )
    else:
        raise RuntimeError("Malformed /orders response: expected a collection")

    if len(orders) > 200:
        raise RuntimeError(
            f"Malformed /orders response: page contains {len(orders)} orders, exceeding 200"
        )
    if not orders:
        log.info("SKIP no new orders after last_seq=%d; no POST performed", last_seq)
        return {
            "status": "success",
            "processed": 0,
            "posted": False,
            "last_seq": last_seq,
        }

    required_order_fields = {"seq", "date", "region", "units"}
    price_field_names = ("unit_price_minor", "unit_price_cents")
    seen_sequences = set()
    sequences = []
    total_units = 0
    total_revenue_cents = 0
    revenue_by_region_cents = defaultdict(int)

    for index, order in enumerate(orders):
        if not isinstance(order, dict) or not required_order_fields.issubset(order):
            raise RuntimeError(
                f"Malformed order at index {index}: missing one or more required fields"
            )

        present_price_fields = [name for name in price_field_names if name in order]
        if not present_price_fields:
            raise RuntimeError(
                f"Malformed order at index {index}: missing unit price in minor currency units"
            )
        if len(present_price_fields) == 2 and order["unit_price_minor"] != order["unit_price_cents"]:
            raise RuntimeError(
                f"Malformed order at index {index}: conflicting unit price fields"
            )
        price_field = present_price_fields[0]

        seq = require_int(order["seq"], f"orders[{index}].seq")
        units = require_int(order["units"], f"orders[{index}].units")
        unit_price_cents = require_int(
            order[price_field],
            f"orders[{index}].{price_field}",
        )
        region = order["region"]
        order_date = order["date"]

        if seq <= last_seq:
            raise RuntimeError(
                f"Malformed order at index {index}: seq {seq} is not greater than checkpoint {last_seq}"
            )
        if seq in seen_sequences:
            raise RuntimeError(f"Malformed /orders response: duplicate seq {seq}")
        if type(region) is not str or not region:
            raise RuntimeError(
                f"Malformed order at index {index}: region must be a nonempty string"
            )
        if type(order_date) is not str:
            raise RuntimeError(
                f"Malformed order at index {index}: date must be YYYY-MM-DD"
            )
        try:
            parsed_date = Date.fromisoformat(order_date)
        except ValueError as exc:
            raise RuntimeError(
                f"Malformed order at index {index}: invalid date {order_date!r}"
            ) from exc
        if parsed_date.isoformat() != order_date:
            raise RuntimeError(
                f"Malformed order at index {index}: date must be exactly YYYY-MM-DD"
            )
        if units < 0 or unit_price_cents < 0:
            raise RuntimeError(
                f"Malformed order at index {index}: units and unit price must be nonnegative"
            )

        seen_sequences.add(seq)
        sequences.append(seq)
        revenue_cents = units * unit_price_cents
        total_units += units
        total_revenue_cents += revenue_cents
        revenue_by_region_cents[region] += revenue_cents

    payload = {
        "batch_start_seq": min(sequences),
        "batch_end_seq": max(sequences),
        "order_count": len(orders),
        "total_units": total_units,
        "total_revenue_cents": total_revenue_cents,
        "revenue_by_region_cents": dict(revenue_by_region_cents),
    }
    if set(payload) != expected_payload_keys:
        raise AssertionError("Internal payload key invariant failed")

    encoded_payload = json.dumps(
        payload,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    log.info(
        "PHASE POST batch seq=%d..%d count=%d",
        payload["batch_start_seq"],
        payload["batch_end_seq"],
        payload["order_count"],
    )
    request = urllib.request.Request(
        f"{base_url}/batches",
        data=encoded_payload,
        method="POST",
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
            post_status = response.status
            response.read()
    except urllib.error.HTTPError as exc:
        body = exc.read()
        raise RuntimeError(
            f"POST /batches failed with HTTP {exc.code}: {body[:500]!r}"
        ) from exc
    except Exception as exc:
        raise RuntimeError(f"POST /batches failed: {exc}") from exc

    if not 200 <= post_status < 300:
        raise RuntimeError(
            f"POST /batches returned non-2xx HTTP {post_status}"
        )

    log.info("PHASE posted batch successfully with HTTP %d", post_status)
    return {
        "status": "success",
        "processed": len(orders),
        "posted": True,
        "batch": payload,
        "http_status": post_status,
    }
